package cn.zhuatech.cashflowai;
import cn.zhuatech.cashflowai.service.CashflowForecastService; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import static org.assertj.core.api.Assertions.assertThat;
class CashflowForecastServiceTests{private final CashflowForecastService service=new CashflowForecastService();@Test void flagsLiquidityGap(){var r=service.forecast(new CashflowForecastService.Request("ZH-SH",new BigDecimal("120000"),new BigDecimal("180000"),new BigDecimal("520000"),new BigDecimal("160000"),new BigDecimal("50000"),62));assertThat(r.riskLevel()).isEqualTo("HIGH");assertThat(r.liquidityGap()).isPositive();}@Test void keepsBalancedEntityLowRisk(){var r=service.forecast(new CashflowForecastService.Request("ZH-SZ",new BigDecimal("800000"),new BigDecimal("600000"),new BigDecimal("520000"),new BigDecimal("40000"),new BigDecimal("300000"),91));assertThat(r.riskLevel()).isEqualTo("LOW");assertThat(r.runwayDays()).isGreaterThan(30);}}
